class Solution {
  public int findDerangement(int n) {
    final long MOD = 1_000_000_007L;
    long a = 1, b = 0; // D(0), D(1)
    // D(i) = (i - 1) * (D(i - 1) + D(i - 2))
    for (int i = 2; i <= n; i++) {
      long c = (i - 1) * ((a + b) % MOD) % MOD;
      a = b;
      b = c;
    }
    return (int) (n == 0 ? 1 : b);
  }
}
